const PAPVER='pap-0.9';
/* ============ spillets tilstand: tøjet heksen har på, værelsets indretning, stjerner og hvad man har fået; gemmes i browseren ============ */
const SPIL={look:{},farver:{},rum:{},stj:0,har:[],pause:false,rebake:false,room:null,arrive(){}};
try{const s=JSON.parse(localStorage.getItem('magiske-mig-pap')||'null');if(s){if(s.look)for(const k of['hat','hår','tøj','kappe','støvler','tilbehør'])if(typeof s.look[k]==='string')SPIL.look[k]=s.look[k];
  if(s.rum)for(const k in s.rum)if(Number.isInteger(s.rum[k]))SPIL.rum[k]=s.rum[k];if(Number.isFinite(s.stj))SPIL.stj=Math.max(0,Math.floor(s.stj));if(Array.isArray(s.har))SPIL.har=s.har.filter(x=>typeof x==='string').slice(0,200);if(Number.isInteger(s.eliksir))SPIL.eliksir=s.eliksir;if(s.farver)for(const k of['tøj','hat','kappe','støvler','hår'])if(/^#[0-9a-f]{6}$/i.test(s.farver[k]||''))SPIL.farver[k]=s.farver[k]}}catch(_){}
SPIL.save=()=>{try{localStorage.setItem('magiske-mig-pap',JSON.stringify({look:SPIL.look,farver:SPIL.farver,rum:SPIL.rum,stj:SPIL.stj,har:SPIL.har,eliksir:SPIL.eliksir||0}))}catch(_){}};
/* det man kan få i Boblebutikken; resten har heksen fra starten */
SPIL.VARER=[['tøj','månekjole','Månekjolen'],['tøj','blomsterkjole','Blomsterkjolen'],['tøj','stribekjole','Den stribede kjole'],['tøj','prikkjole','Den prikkede kjole'],['tøj','hjertekjole','Hjertekjolen'],['tøj','knapkjole','Knapkjolen'],['tøj','lagkjole','Lagkjolen'],['tøj','forklædekjole','Forklædekjolen'],['tøj','kortkjole','Den korte kjole'],
  ['hat','kort','Den korte hat'],['hat','høj','Den høje hat'],['hat','blomst','Blomsterhatten'],['hat','krone','Kronen'],['hat','baret','Baretten'],['hat','sløjfe','Sløjfen'],['hat','hue','Huen'],
  ['kappe','måne','Månekappen'],['kappe','takket','Den takkede kappe'],['kappe','blomster','Blomsterkappen'],['kappe','stribet','Den stribede kappe'],['kappe','pelskant','Kappen med pelskant'],['kappe','hætte','Kappen med hætte'],
  ['støvler','spidse','De spidse sko'],['støvler','høje','De høje støvler'],['støvler','ballerina','Ballerinaskoene'],['støvler','gummi','Gummistøvlerne'],['støvler','pels','Pelsstøvlerne'],['støvler','sandaler','Sandalerne'],['støvler','krul','Skoene med krøllede tæer'],['støvler','spænde','Spændeskoene'],['støvler','knap','Knapstøvlerne'],['tøj','eventyrer','Eventyrer-tøjet'],['tilbehør','taske','Skuldertasken'],['hat','nathat','Nattehatten'],['hat','eventyrhat','Eventyrhatten'],['hår','fletning','Fletningen'],['hår','bølger','Bølgerne'],['tøj','festkjole','Festkjolen'],['tøj','skovløber','Skovløber-tøjet'],['tøj','opdager','Opdager-tøjet'],['tøj','rejsekappe','Rejsefrakken'],['kappe','stjerne','Stjernekappen'],['kappe','kort','Læderkappen'],['tilbehør','rygsæk','Rygsækken'],['tilbehør','tørklæde','Tørklædet']];
SPIL.ejer=(k,v)=>!SPIL.VARER.some(w=>w[0]===k&&w[1]===v)||SPIL.har.includes(k+':'+v);
for(const k in SPIL.look)if(!SPIL.ejer(k,SPIL.look[k]))SPIL.har.push(k+':'+SPIL.look[k]);/* det hun allerede har på, er hendes */
/* hele heksens udseende: tøjvalgene og farverne samlet, sådan som figuren skal have dem */
SPIL.lookFuld=()=>{const l=Object.assign({},SPIL.look),f=SPIL.farver,col={};for(const k of['tøj','hat','kappe','støvler'])if(f[k])col[k]=f[k];l.col=col;if(f.hår)l.hair=[f.hår,hexOf(shade(f.hår,.25)),hexOf(shade(f.hår,-.35))];return l};
